def compress_consecutive_ranges(lst):
    if not lst:
        return []
    ranges = []
    start = lst[0]
    prev = lst[0]
    for x in lst[1:]:
        if x == prev + 1:
            prev = x
        else:
            ranges.append([start, prev])
            start = x
            prev = x
    ranges.append([start, prev])
    return ranges

