def longest_increasing_run_start(lst):
    n = len(lst)
    if n == 0:
        return -1
    best_len = 1
    best_start = 0
    cur_len = 1
    cur_start = 0
    for i in range(1, n):
        if lst[i] > lst[i - 1]:
            cur_len += 1
        else:
            cur_len = 1
            cur_start = i
        if cur_len > best_len:
            best_len = cur_len
            best_start = cur_start
    return best_start

