def unflatten_tuple_keys(d):
    out = {}
    for path, value in d.items():
        node = out
        for key in path[:-1]:
            if key not in node:
                node[key] = {}
            node = node[key]
        node[path[-1]] = value
    return out

def collatz_max_value(n):
    current = n
    maximum = n
    while current != 1:
        if current % 2 == 0:
            current //= 2
        else:
            current = current * 3 + 1
        if current > maximum:
            maximum = current
    return maximum

